mapper.select:
SELECT COUNT(*)
FROM match_bid
WHERE match_id = #{matchId}
  AND lawyer_id = #{lawyerId}
  AND deleted = 1

mapper.update:
UPDATE match_bid
SET status = #{status}
WHERE id = #{bidId}
  AND deleted = 1

UPDATE match_bid
SET status = 'REJECTED'
WHERE match_id = #{matchId}
  AND id != #{selectedBidId}
  AND deleted = 1
